"""Self-contained teaching examples for the complete editorial review."""
RECIPES = {}

def add(slug, code, template, interpretation, checks, packages=()):
    RECIPES[slug] = dict(packages=list(packages), data_shape="一行一条观测；列名和单位须与代码一致。示例仅用于教学。", example_code=code, your_data_code=template, interpretation=interpretation, assumption_checks=checks, key_output=["估计量", "不确定性", "模型诊断"], report_template="报告研究设计、样本量、方法、估计及区间；说明假设检查与数据处理。", common_errors=["不要把合成数据的结果当作真实心理学结论。"], validation_code="", verified=False)

SURVEY = 'd <- read.csv("cross_sectional_survey.csv")\n'
LEARNING = 'd <- read.csv("learning_experiment.csv")\n'
OWN = 'd <- read.csv("your_data.csv")\n'
add("simple-linear-regression", SURVEY+'fit <- lm(well_being ~ stress, data=d)\nprint(summary(fit))\nprint(confint(fit))\nstopifnot(coef(fit)[2] < 0)\n', OWN+'fit <- lm(outcome ~ predictor, data=d)\nsummary(fit)\nconfint(fit)\nplot(fit)\n', "summary 中 stress 的系数是压力增加一个单位对应的平均幸福感差异；confint 给出系数区间。检查残差图后再解释，回归方向不证明因果。", ["预测变量与结果的关系近似线性", "观测独立，核对残差与异常点"])
add("manova", SURVEY+'fit <- manova(cbind(stress, well_being) ~ factor(gender), data=d)\nprint(summary(fit, test="Pillai"))\n', OWN+'fit <- manova(cbind(outcome1, outcome2) ~ factor(group), data=d)\nsummary(fit, test="Pillai")\n', "Pillai 行的整体检验考察两项结果的联合均值向量，不告诉你哪一项单独不同；后续分析需要安排多重比较。", ["多项连续结果不完全共线", "组内协方差结构、独立性与异常点需检查"])
add("stepwise-regression", SURVEY+'full <- lm(well_being ~ stress + social_support + age, data=d)\nfit <- step(full, direction="backward", trace=0)\nprint(formula(fit))\nprint(AIC(full, fit))\n', OWN+'full <- lm(outcome ~ x1 + x2 + x3, data=d)\nfit <- step(full, direction="backward", trace=0)\nformula(fit)\n# 另用独立验证数据评估预测；不要把筛选后的p值当作预设检验\n', "输出公式显示按 AIC 后退筛选保留的项。AIC 较低只是候选模型之间的相对比较；重复筛选后的通常 p 值和区间没有包含模型选择的不确定性。", ["仅作探索，不替代预先指定的理论模型", "评估稳定性和样本外表现"])
add("chi-square-test", 'counts <- matrix(c(40,20,25,35), nrow=2, byrow=TRUE, dimnames=list(condition=c("A","B"), completed=c("yes","no")))\nfit <- chisq.test(counts, correct=FALSE)\nprint(fit)\nprint(fit$expected)\nprint(fit$stdres)\nstopifnot(all(fit$expected >= 5))\n', OWN+'counts <- table(d$group, d$response)\nfit <- chisq.test(counts)\nfit\nfit$expected\n# 频数过小的2×2表可考虑 fisher.test(counts)\n', "本例检验条件与完成情况是否关联。expected 是独立性成立时的期望频数，stdres 帮助定位偏离；检验结果不表示关联强度或干预的因果作用。", ["输入频数而非百分比", "每人仅贡献一个独立记录；检查期望频数"])
add("post-hoc-comparison", 'set.seed(42)\nd <- data.frame(group=factor(rep(c("control","retrieval","rereading"), each=60)), gain=rnorm(180, rep(c(20,26,23), each=60), 5))\nfit <- aov(gain ~ group, data=d)\nprint(summary(fit))\nprint(TukeyHSD(fit))\n', OWN+'d$group <- factor(d$group)\nfit <- aov(outcome ~ group, data=d)\nTukeyHSD(fit)\n', "Tukey 输出 diff、lwr、upr 和 p adj，分别为组均值差、同时置信区间和调整后 p 值。方向依比较名称读取；不能拿未调整的多次 t 检验替代。", ["独立组、方差齐性与残差条件", "明确预设比较还是探索性的两两比较"])
add("nonparametric-test", LEARNING+'fit <- wilcox.test(gain ~ condition, data=d, exact=FALSE)\nprint(fit)\nprint(aggregate(gain ~ condition, d, median))\n', OWN+'wilcox.test(outcome ~ group, data=d, exact=FALSE)\n# 配对数据改用 wilcox.test(d$before, d$after, paired=TRUE)\n', "Wilcoxon 秩和检验使用排序信息。输出的 p 值不是两组中位数差的大小；只有分布形状等条件合适时，才可解释为位置差异。示例关闭精确算法以处理并列值。", ["先区分独立样本与配对样本", "非参数检验仍有独立性和分布解释的条件"])
add("bootstrap", SURVEY+'set.seed(42)\nB <- 1000\nx <- d$stress\nestimates <- replicate(B, mean(sample(x, length(x), replace=TRUE)))\nprint(c(mean=mean(x), bootstrap_se=sd(estimates)))\nprint(quantile(estimates, c(.025,.975)))\nstopifnot(sd(estimates)>0)\n', OWN+'set.seed(42)\nx <- na.omit(d$outcome)\nestimates <- replicate(2000, mean(sample(x, length(x), replace=TRUE)))\nsd(estimates)\nquantile(estimates, c(.025,.975))\n', "bootstrap_se 为重抽样均值的标准差；两端分位数构成百分位区间，不是 BCa 区间。本例按独立个体抽样；聚类或纵向数据必须调整重抽样单位。", ["重抽样单位与研究设计匹配", "重复次数与区间方法需要报告"])
add("sobel-test", SURVEY+'a_fit <- lm(stress ~ social_support, data=d)\nb_fit <- lm(well_being ~ social_support + stress, data=d)\na <- coef(a_fit)[2]; b <- coef(b_fit)[3]\nsa <- sqrt(vcov(a_fit)[2,2]); sb <- sqrt(vcov(b_fit)[3,3])\nse <- sqrt(b^2*sa^2 + a^2*sb^2)\nz <- a*b/se\nprint(c(indirect=a*b, se=se, z=z, p=2*pnorm(-abs(z))))\n', OWN+'a_fit <- lm(mediator ~ predictor, data=d)\nb_fit <- lm(outcome ~ predictor + mediator, data=d)\na <- coef(a_fit)[2]; b <- coef(b_fit)[3]\nse <- sqrt(b^2*vcov(a_fit)[2,2] + a^2*vcov(b_fit)[3,3])\nz <- a*b/se\nc(indirect=a*b, z=z, p=2*pnorm(-abs(z)))\n', "indirect 是 a×b 的间接路径乘积；z 与 p 使用正态近似。乘积的抽样分布可能偏斜，尤其小样本时宜考虑合适的 Bootstrap 区间；横断面路径不是因果中介证据。", ["这里仅适用连续变量的简单线性路径", "时间顺序、混杂控制和样本量需要论证"])
add("simple-slope-test", SURVEY+'d$x <- d$social_support-mean(d$social_support)\nd$w <- d$stress-mean(d$stress)\nfit <- lm(well_being ~ x*w, data=d)\nw_values <- c(-sd(d$w),0,sd(d$w))\nresults <- do.call(rbind,lapply(w_values,function(w){\n L <- c(0,1,0,w)\n slope <- sum(L*coef(fit)); se <- sqrt(drop(t(L)%*%vcov(fit)%*%L))\n data.frame(moderator=w,slope=slope,se=se,lower=slope-qt(.975,df.residual(fit))*se,upper=slope+qt(.975,df.residual(fit))*se)\n}))\nprint(results)\n', OWN+'d$x <- d$predictor-mean(d$predictor)\nd$w <- d$moderator-mean(d$moderator)\nfit <- lm(outcome ~ x*w, data=d)\n# w为中心化后的调节值；请确认系数顺序为截距、x、w、x:w\nw <- 0\nL <- c(0,1,0,w)\nslope <- sum(L*coef(fit))\nse <- sqrt(drop(t(L)%*%vcov(fit)%*%L))\nc(slope=slope,se=se)\n', "每行给出压力处于均值及均值上下一个标准差时，支持与幸福感关系的斜率和区间。区间来自完整协方差矩阵；不能因为一条显著、另一条不显著就断言两条斜率不同。", ["先检查交互项与线性条件", "选取数据范围内有意义的调节值"])
for slug, formula, random, dataset in [
    ("hlm","achievement ~ motivation + teacher_support","~1|class_id","nested_classrooms"),
    ("null-model","achievement ~ 1","~1|class_id","nested_classrooms"),
    ("random-slope-model","achievement ~ motivation + teacher_support","list(class_id=nlme::pdDiag(~motivation))","nested_classrooms"),
    ("growth-model","outcome ~ time*treatment","~time|id","longitudinal_growth")]:
    code=f'd <- read.csv("{dataset}.csv")\nfit <- nlme::lme({formula}, random={random}, data=d, method="REML", control=nlme::lmeControl(opt="optim"))\nprint(summary(fit))\nprint(nlme::VarCorr(fit))\nstopifnot(all(is.finite(nlme::fixef(fit))))\n'
    add(slug,code,OWN+f'# 把结果、预测项和分组ID替换为实际列名\nfit <- nlme::lme({formula}, random={random}, data=d, method="REML")\nsummary(fit)\nnlme::VarCorr(fit)\n', "summary 的固定效应表描述平均关系；VarCorr 描述组间随机效应和组内残差。时间×组别项描述轨迹差异。随机斜率示例用对角协方差约束，需要依据设计论证；核对收敛与残差后再报告。", ["确认组内多条观测与足够组数", "检查随机效应结构、收敛和时间编码"], ["nlme"])

RECIPES['hlm']['interpretation']='固定效应表的 motivation 为相同班级支持水平下，动机每增加一单位对应的平均成绩差异；teacher_support 为班级支持的模型条件关系。VarCorr 列出班级随机截距方差与学生层残差方差。当前模型未将动机分解为组内与组间项，不能据此直接宣称纯组内效应。'
RECIPES['null-model']['interpretation']='这里只有总体截距，没有预测项。VarCorr 的班级随机截距方差与残差方差之和构成模型总方差；前者除以总方差是该连续结果随机截距模型的 ICC。空模型提供基线，不解释班级差异的成因。'
RECIPES['random-slope-model']['interpretation']='VarCorr 中 motivation 的随机效应方差反映动机与成绩关系在班级间的变化；固定 motivation 系数描述平均斜率。本例 pdDiag 将随机截距与斜率协方差约束为零，是演示性限制，不是数据证明二者独立。'
RECIPES['growth-model']['interpretation']='固定 time 系数描述参照组的平均单位时间变化；time:treatment 项描述另一组与参照组的变化速率差异。VarCorr 表示个体起点、斜率与残差变异。time=0 必须有合理含义；轨迹差异的因果解读还取决于分组设计。'
